"""Render the standalone bash script emitted by ``isholate dump-script``.

The rendered script depends only on ``bash`` and ``incus``: it creates and
provisions the container on first use, then enters it with a login shell.
"""

from __future__ import annotations

import shlex

BASE_PACKAGES = ("python3", "sudo", "bubblewrap", "nodejs", "npm", "socat", "zsh")

_TEMPLATE = """\
#!/usr/bin/env bash
# Standalone re-creation of an isholate container.
# Generated by `isholate dump-script`; needs only bash and incus.
#
# Usage: {script_name} [CONTAINER_NAME]
set -euo pipefail

IMAGE={image}
SHELL_PATH={shell}
USERNAME={username}
DEFAULT_NAME={default_name}
SANDBOX_RUNTIME={sandbox_runtime}
PACKAGES={packages}

NAME="${{1:-$DEFAULT_NAME}}"

provision() {{
  echo "Creating container '$NAME' from $IMAGE..." >&2
  incus init "$IMAGE" "$NAME" --config security.nesting=true
  incus start "$NAME"

  echo "Waiting for network..." >&2
  local i
  for i in $(seq 1 60); do
    if incus exec "$NAME" -- sh -c 'getent hosts archive.ubuntu.com >/dev/null 2>&1 || getent hosts deb.debian.org >/dev/null 2>&1 || getent hosts fedoraproject.org >/dev/null 2>&1'; then
      break
    fi
    if [ "$i" -eq 60 ]; then
      echo "error: container '$NAME' has no network after 60s" >&2
      exit 1
    fi
    sleep 1
  done

  echo "Creating user '$USERNAME'..." >&2
  incus exec "$NAME" -- userdel -r ubuntu >/dev/null 2>&1 || true
  incus exec "$NAME" -- useradd -m -s "$SHELL_PATH" "$USERNAME"

  echo "Installing base packages ($PACKAGES)..." >&2
  incus exec "$NAME" --env DEBIAN_FRONTEND=noninteractive -- sh -c "
    if command -v apt-get >/dev/null 2>&1; then
      apt-get update -qq && apt-get install -qq -y --no-install-recommends $PACKAGES
    elif command -v dnf >/dev/null 2>&1; then
      dnf install -y $PACKAGES
    else
      echo 'error: no supported package manager (apt-get/dnf) found' >&2
      exit 1
    fi"

  echo "Installing $SANDBOX_RUNTIME..." >&2
  incus exec "$NAME" \\
    --env npm_config_update_notifier=false \\
    --env npm_config_audit=false \\
    --env npm_config_fund=false \\
    -- npm install -g --loglevel=error "$SANDBOX_RUNTIME"
}}

if ! incus info "$NAME" >/dev/null 2>&1; then
  trap 'echo "error: provisioning failed; removing $NAME" >&2; incus delete --force "$NAME" >/dev/null 2>&1 || true' EXIT
  provision
  trap - EXIT
elif [ "$(incus list "^${{NAME}}\\$" --format csv --columns s)" != "RUNNING" ]; then
  incus start "$NAME"
fi

CONTAINER_UID="$(incus exec "$NAME" -- id -u "$USERNAME")"
exec incus exec "$NAME" \\
  --user "$CONTAINER_UID" \\
  --cwd "/home/$USERNAME" \\
  --env "HOME=/home/$USERNAME" \\
  --env "USER=$USERNAME" \\
  --env "LOGNAME=$USERNAME" \\
  -- "$SHELL_PATH" -l
"""


def render_dump_script(
    *,
    image: str,
    shell: str,
    username: str,
    default_name: str,
    sandbox_runtime_version: str,
    script_name: str = "isholate.sh",
) -> str:
    """Return the standalone bash script text.

    Every interpolated value is ``shlex.quote``-d so unusual usernames or
    image names cannot break out of their assignment.
    """
    return _TEMPLATE.format(
        script_name=script_name,
        image=shlex.quote(image),
        shell=shlex.quote(shell),
        username=shlex.quote(username),
        default_name=shlex.quote(default_name),
        sandbox_runtime=shlex.quote(
            f"@anthropic-ai/sandbox-runtime@{sandbox_runtime_version}"
        ),
        packages=shlex.quote(" ".join(BASE_PACKAGES)),
    )
